package dev.eugheist.tc4modern;

import net.minecraft.client.Minecraft;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.inventory.ClickType;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;

/** Native filter paging, legacy save migration, real seed consumption and entropy equivalence. */
@EventBusSubscriber(modid=TC4Modern.MODID,value=Dist.CLIENT)
public final class GolemUpgradeAudit {
 static final BlockPos BASE=new BlockPos(170,121,-90),WHEAT=BASE.offset(-4,0,3),CARROT=BASE.offset(-2,0,3),WART=BASE.offset(0,0,3),COCOA=BASE.offset(2,1,3),POD=BASE.offset(4,1,3);
 static int ticks,stage;static boolean produceChecked;static StrawGolem fire,order,entropy;static volatile boolean ready,done;
 static void check(boolean condition,String message){if(!condition)throw new IllegalStateException("TC4_UPGRADE FAIL "+message);System.out.println("TC4_UPGRADE PASS "+message);}
 static StrawGolem make(ServerPlayer p,BlockPos home,int core){var g=new StrawGolem(Golemancy.ENTITY.get(),p.level());g.material(GolemMaterial.TALLOW,true);g.home=home;g.homeFace=Direction.UP;g.moveTo(home.getX()+.5,home.getY(),home.getZ()+.5,180,0);g.getEntityData().set(StrawGolem.CORE,(byte)core);g.restrictTo(home,(int)Math.ceil(g.range()));p.level().addFreshEntity(g);return g;}
 static void setup(ServerPlayer p){var l=p.serverLevel();p.removeAllEffects();p.setHealth(p.getMaxHealth());p.setGameMode(GameType.CREATIVE);p.getInventory().clearContent();p.connection.teleport(BASE.getX()+7,BASE.getY()+3,BASE.getZ()-6,45,20);p.getAbilities().flying=true;p.onUpdateAbilities();l.setDayTime(6000);l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_RANDOMTICKING).set(0,l.getServer());l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DOMOBSPAWNING).set(false,l.getServer());
  for(var e:l.getEntitiesOfClass(Entity.class,new AABB(BASE).inflate(22)))if(!(e instanceof net.minecraft.world.entity.player.Player))e.discard();for(int x=-10;x<=12;x++)for(int z=-8;z<=10;z++)for(int y=-1;y<=4;y++)l.setBlock(BASE.offset(x,y,z),(y==-1?Blocks.STONE:Blocks.AIR).defaultBlockState(),3);l.getEntitiesOfClass(ItemEntity.class,new AABB(BASE).inflate(22)).forEach(Entity::discard);
  var biome=l.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.BIOME).getHolderOrThrow(MagicalForestContent.BIOME);for(int cx=-1;cx<=1;cx++)for(int cz=-1;cz<=1;cz++){var chunk=l.getChunk((BASE.getX()>>4)+cx,(BASE.getZ()>>4)+cz);chunk.fillBiomesFromNoise((x,y,z,sampler)->biome,l.getChunkSource().randomState().sampler());chunk.setUnsaved(true);}
  var legacy=new CompoundTag();legacy.putByte("Upgrades",(byte)32);var migrated=new StrawGolem(Golemancy.ENTITY.get(),l);migrated.material(GolemMaterial.TALLOW,true);migrated.restoreData(legacy);check(migrated.upgrades(2)==2&&migrated.range()==24,"0.17.71 byte save keeps two water upgrades");migrated.restoreUpgrades(0);check(migrated.upgradeCount()==0&&migrated.range()==16,"clearing upgrades refreshes attributes and range");
  fire=make(p,BASE.offset(0,0,-2),2);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Golemancy.upgrade(3),3));fire.mobInteract(p,InteractionHand.MAIN_HAND);fire.mobInteract(p,InteractionHand.MAIN_HAND);fire.mobInteract(p,InteractionHand.MAIN_HAND);check(fire.upgrades(3)==2&&fire.filterCount()==18&&p.getMainHandItem().getCount()==1,"actual two fire upgrades give18 filters and reject third");fire.filters.setItem(0,new ItemStack(Items.OAK_PLANKS));fire.filters.setItem(6,new ItemStack(Items.IRON_INGOT));fire.filters.setItem(12,new ItemStack(Items.GOLD_INGOT));fire.filters.setItem(17,new ItemStack(Items.EMERALD));check(fire.accepts(new ItemStack(Items.EMERALD))&&!fire.accepts(new ItemStack(Items.DIAMOND)),"gather uses filters on third page");
  var serialized=new CompoundTag();fire.addAdditionalSaveData(serialized);var copy=new StrawGolem(Golemancy.ENTITY.get(),l);copy.readAdditionalSaveData(serialized);check(copy.upgrades(3)==2&&copy.filters.getItem(17).is(Items.EMERALD),"new integer upgrade data and18 filters survive save");var placer=fire.asItem();var returned=new StrawGolem(Golemancy.ENTITY.get(),l);returned.material(GolemMaterial.TALLOW,true);returned.restoreItem(placer);check(returned.upgrades(3)==2&&returned.filters.getItem(17).is(Items.EMERALD),"fire pages survive bell item payload");
  entropy=make(p,BASE.offset(-6,0,-2),-1);check(entropy.installUpgrade(5)&&entropy.installUpgrade(5),"two entropy upgrades install");entropy.filters.setItem(0,new ItemStack(Items.OAK_PLANKS));check(entropy.accepts(new ItemStack(Items.BIRCH_PLANKS))&&!entropy.accepts(new ItemStack(Items.IRON_INGOT)),"entropy matches wood OreDictionary equivalent only");var strict=new StrawGolem(Golemancy.ENTITY.get(),l);strict.filters.setItem(0,new ItemStack(Items.OAK_PLANKS));check(!strict.accepts(new ItemStack(Items.BIRCH_PLANKS)),"without entropy filter stays exact");
  var attacker=new net.minecraft.world.entity.monster.Zombie(EntityType.ZOMBIE,l);attacker.setPos(entropy.position().add(1,0,0));attacker.setNoAi(true);l.addFreshEntity(attacker);float hp=attacker.getHealth();entropy.hurt(l.damageSources().mobAttack(attacker),1);float reflected=hp-attacker.getHealth();check(reflected>=3&&reflected<=7,"entropy reflects original4to7 damage adjusted by zombie armor");float stable=attacker.getHealth();entropy.invulnerableTime=0;entropy.hurt(l.damageSources().thorns(attacker),1);check(attacker.getHealth()==stable,"thorns damage does not recursively reflect");attacker.discard();
  var pig=new net.minecraft.world.entity.animal.Pig(EntityType.PIG,l);pig.setPos(fire.position().add(1,0,0));pig.setNoAi(true);l.addFreshEntity(pig);check(fire.doHurtTarget(pig)&&pig.getRemainingFireTicks()==160,"fire upgrade attack ignites for8 seconds");pig.discard();
  order=make(p,BASE.offset(0,0,2),3);check(order.installUpgrade(4),"order upgrade installs on harvester");
  l.setBlock(WHEAT.below(),Blocks.FARMLAND.defaultBlockState(),3);l.setBlock(WHEAT,((CropBlock)Blocks.WHEAT).getStateForAge(7),3);l.setBlock(CARROT.below(),Blocks.FARMLAND.defaultBlockState(),3);l.setBlock(CARROT,((CropBlock)Blocks.CARROTS).getStateForAge(0),3);l.setBlock(WART.below(),Blocks.SOUL_SAND.defaultBlockState(),3);l.setBlock(WART,Blocks.NETHER_WART.defaultBlockState().setValue(NetherWartBlock.AGE,0),3);l.setBlock(COCOA.east(),Blocks.JUNGLE_LOG.defaultBlockState(),3);l.setBlock(COCOA,Blocks.COCOA.defaultBlockState().setValue(CocoaBlock.FACING,Direction.EAST).setValue(CocoaBlock.AGE,0),3);l.setBlock(POD.above(),TC4Modern.GREATWOOD_LOG.get().defaultBlockState(),3);l.setBlock(POD,BasicsContent.MANA_POD.get().defaultBlockState().setValue(ManaPodBlock.AGE,0),3);((ManaPodEntity)l.getBlockEntity(POD)).aspect=thaumcraft.api.aspects.Aspect.FIRE;
  var seed=new ItemEntity(l,WHEAT.getX()+.5,WHEAT.getY()+.1,WHEAT.getZ()+.5,new ItemStack(Items.WHEAT_SEEDS));seed.setDeltaMovement(Vec3.ZERO);l.addFreshEntity(seed);
  p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.getInventory().setItem(1,new ItemStack(Items.DIAMOND,3));p.connection.teleport(fire.getX()+2,fire.getY()+1,fire.getZ()-2,45,15);p.openMenu(fire,b->b.writeVarInt(fire.getId()));ready=true;
 }
 static void advance(ServerPlayer p){if(stage>=5)return;var l=p.serverLevel();var current=java.util.List.of(WHEAT,CARROT,WART,COCOA,POD).get(stage);var state=l.getBlockState(current);boolean replanted=switch(stage){case 0->state.is(Blocks.WHEAT)&&state.getValue(CropBlock.AGE)==0;case 1->state.is(Blocks.CARROTS)&&state.getValue(CropBlock.AGE)==0;case 2->state.is(Blocks.NETHER_WART)&&state.getValue(NetherWartBlock.AGE)==0;case 3->state.is(Blocks.COCOA)&&state.getValue(CocoaBlock.AGE)==0&&state.getValue(CocoaBlock.FACING)==Direction.EAST;default->state.is(BasicsContent.MANA_POD.get())&&state.getValue(ManaPodBlock.AGE)==0&&((ManaPodEntity)l.getBlockEntity(POD)).aspect==thaumcraft.api.aspects.Aspect.FIRE;};if(!replanted)return;
 check(true,"natural mature crop harvested and replanted stage "+stage+" "+state);
 if(stage==0){produceChecked=l.getEntitiesOfClass(ItemEntity.class,new AABB(BASE).inflate(12)).stream().anyMatch(e->e.getItem().is(Items.WHEAT));check(produceChecked,"wheat produce remains after replanting");}
 if(stage==3){int beans=l.getEntitiesOfClass(ItemEntity.class,new AABB(BASE).inflate(12)).stream().filter(e->e.getItem().is(Items.COCOA_BEANS)).mapToInt(e->e.getItem().getCount()).sum();check(beans==2,"replanting consumes exactly one of three real cocoa beans");}
 l.getEntitiesOfClass(ItemEntity.class,new AABB(BASE).inflate(12)).forEach(Entity::discard);stage++;switch(stage){case 1->l.setBlock(CARROT,((CropBlock)Blocks.CARROTS).getStateForAge(7),3);case 2->l.setBlock(WART,Blocks.NETHER_WART.defaultBlockState().setValue(NetherWartBlock.AGE,3),3);case 3->l.setBlock(COCOA,Blocks.COCOA.defaultBlockState().setValue(CocoaBlock.FACING,Direction.EAST).setValue(CocoaBlock.AGE,2),3);case 4->{l.setBlock(POD,BasicsContent.MANA_POD.get().defaultBlockState().setValue(ManaPodBlock.AGE,7),3);((ManaPodEntity)l.getBlockEntity(POD)).aspect=thaumcraft.api.aspects.Aspect.FIRE;}default->{}}
 }
 static void finish(ServerPlayer p){var l=p.serverLevel();for(var at:java.util.List.of(WHEAT,CARROT,WART,COCOA,POD))System.out.println("TC4_UPGRADE crop "+at+" "+l.getBlockState(at));check(l.getBlockState(WHEAT).is(Blocks.WHEAT)&&l.getBlockState(WHEAT).getValue(CropBlock.AGE)==0,"order naturally replants wheat using real seeds");check(l.getBlockState(CARROT).is(Blocks.CARROTS)&&l.getBlockState(CARROT).getValue(CropBlock.AGE)==0,"order naturally replants carrots");check(l.getBlockState(WART).is(Blocks.NETHER_WART)&&l.getBlockState(WART).getValue(NetherWartBlock.AGE)==0,"order naturally replants nether wart");check(l.getBlockState(COCOA).is(Blocks.COCOA)&&l.getBlockState(COCOA).getValue(CocoaBlock.AGE)==0&&l.getBlockState(COCOA).getValue(CocoaBlock.FACING)==Direction.EAST,"order replants cocoa facing its original log");check(l.getBlockState(POD).is(BasicsContent.MANA_POD.get())&&l.getBlockState(POD).getValue(ManaPodBlock.AGE)==0&&((ManaPodEntity)l.getBlockEntity(POD)).aspect==thaumcraft.api.aspects.Aspect.FIRE,"order replants mana bean with original aspect");check(stage==5&&produceChecked,"all five natural planting stages finished");check(fire.filters.getItem(6).is(Items.DIAMOND)&&fire.filters.getItem(0).is(Items.OAK_PLANKS)&&fire.filters.getItem(12).is(Items.GOLD_INGOT)&&p.getInventory().getItem(1).getCount()==3,"page edit changes only selected filter and consumes no real item");done=true;}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("tc4modern.golemUpgradeAuditOnly"))return;var mc=Minecraft.getInstance();if(mc.player==null)return;ticks++;if(ticks==10&&mc.player.isDeadOrDying())mc.player.respawn();var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==40)server.execute(()->setup(server.getPlayerList().getPlayer(id)));
  if(ticks==100){check(ready&&mc.screen instanceof GolemClient.Screen,"real upgraded golem GUI opens");var menu=(GolemMenu)mc.player.containerMenu;check(menu.pages()==3&&menu.getSlot(0).getItem().is(Items.OAK_PLANKS),"client sees three pages and first filter");mc.gameMode.handleInventoryButtonClick(menu.containerId,67);}
  if(ticks==120){var menu=(GolemMenu)mc.player.containerMenu;check(menu.page==1&&menu.getSlot(0).getItem().is(Items.IRON_INGOT),"real next-page packet shows second-page filter");mc.gameMode.handleInventoryMouseClick(menu.containerId,34,0,ClickType.PICKUP,mc.player);mc.gameMode.handleInventoryMouseClick(menu.containerId,0,0,ClickType.PICKUP,mc.player);mc.gameMode.handleInventoryMouseClick(menu.containerId,34,0,ClickType.PICKUP,mc.player);}
  if(ticks==140){var menu=(GolemMenu)mc.player.containerMenu;check(menu.getSlot(0).getItem().is(Items.DIAMOND)&&menu.getSlot(0).getItem().getCount()==1,"ghost filter edited on second page");LiquidDeathAudit.shot(mc,"golem-fire-filter-pages.png");mc.gameMode.handleInventoryButtonClick(menu.containerId,67);}
  if(ticks==160){var menu=(GolemMenu)mc.player.containerMenu;check(menu.page==2&&menu.getSlot(0).getItem().is(Items.GOLD_INGOT),"third page contents stay separate");mc.gameMode.handleInventoryButtonClick(menu.containerId,67);}
  if(ticks==180){var menu=(GolemMenu)mc.player.containerMenu;check(menu.page==2,"page cannot exceed maximum");mc.gameMode.handleInventoryButtonClick(menu.containerId,66);mc.gameMode.handleInventoryButtonClick(menu.containerId,66);}
  if(ticks==200){var menu=(GolemMenu)mc.player.containerMenu;check(menu.page==0&&menu.getSlot(0).getItem().is(Items.OAK_PLANKS),"previous-page packets restore first filter");mc.player.closeContainer();server.execute(()->server.getPlayerList().getPlayer(id).connection.teleport(BASE.getX()+7,BASE.getY()+3,BASE.getZ()-6,45,20));}
  if(ticks>200&&ticks%20==0)server.execute(()->advance(server.getPlayerList().getPlayer(id)));if(ticks==600)LiquidDeathAudit.shot(mc,"golem-order-harvest.png");if(ticks%200==0)server.execute(()->{System.out.println("TC4_UPGRADE state working="+order.working()+" alive="+order.isAlive()+" age="+order.tickCount+" biome="+ManaPodBlock.magical(order.level(),POD)+" support="+order.level().getBlockState(POD.above()).is(net.minecraft.tags.BlockTags.LOGS));System.out.println("TC4_UPGRADE progress "+order.position()+" crops="+java.util.List.of(WHEAT,CARROT,WART,COCOA,POD).stream().map(at->at+":"+order.level().getBlockState(at)).toList());});if(ticks==4000)server.execute(()->finish(server.getPlayerList().getPlayer(id)));if(ticks==4020){check(done,"all upgrade checks finished");for(String name:java.util.List.of("Fire","Order","Entropy")){var recipe=ArcaneRecipes.entries().stream().filter(e->e.key().equals("Upgrade"+name)).findFirst().orElseThrow();check(recipe.cost().visSize()==10&&BasicsBookRecipes.researchIcon("UPGRADE"+name.toUpperCase())!=null,"original recipe and research icon "+name);}System.out.println("TC4_UPGRADE ALL PASS");mc.stop();}
 }
}
